# Trifid cube: 3 layers, each 3x3 = 27 cells for 26 letters + '.'
# standard 27-char alphabet: A-Z and '.'
alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZ."

def build_cube(alpha):
    cube={}
